effect.shader:
void main(){
  vec2 uv = acLayerNorm;
  float progress = fract(acTime * speed);
  float rad = angle * 0.017453292519943295;
  vec2 v = normalize(vec2(cos(rad), -sin(rad)));
  float p = dot(uv - vec2(0.5), v) + 0.5;
  float pr = smoothstep(-smoothness, 0.0, p - progress * (1.0 + smoothness));
  float cell = fract(count * p);
  float useFeather = step(1e-6, feather);
  float sHard = step(pr, cell);
  float sSoft = smoothstep(pr, pr + feather, cell);
  float s = mix(sHard, sSoft, useFeather);
  gl_FragColor = vec4(vec3(s), s);
}
